registerItem({
  id: 490276,
  onEquip(ctx) {
    let $param, $g, $r;
    $param = (ctx.readparam("bSpl") / 20);
    $g = ctx.getenchantgrade();
    $r = ctx.getrefine();
    ctx.bonus("bAllTraitStats", 3);
    ctx.bonus("bVariableCastrate", -10);
    if ($r >= 7) {
      ctx.bonus("bSMatk", 3);
      if ($r >= 9) {
        ctx.bonus("bSMatk", 2 * $param);
        ctx.bonus("bWis", 4 * $param);
        if ($r >= 12) {
          ctx.bonus("bFixedCast", -300);
        }
      }
    }
    if ($g >= "ENCHANTGRADE_D") {
      ctx.bonus("bMatkRate", 3);
      ctx.bonus("bSpl", 2);
      if ($g >= "ENCHANTGRADE_C") {
        ctx.bonus("bSMatk", 2);
        if ($g >= "ENCHANTGRADE_B") {
          ctx.bonus("bSMatk", 3);
          ctx.bonus("bRes", 20);
          if ($g >= "ENCHANTGRADE_A") {
            ctx.bonus("bSpl", 2 * (ctx.readparam("bInt") / 15));
          }
        }
      }
    }

  },
});

